function berryHarvest(grid: number[][]): number {
  const n = grid.length;
  const routes: number[][] = [];
  const path: number[] = [];
  const walk = (r: number, c: number): void => {
    if (r >= n || c >= n || grid[r][c] === -1) return;
    path.push(r * n + c);
    if (r === n - 1 && c === n - 1) routes.push([...path]);
    else { walk(r + 1, c); walk(r, c + 1); }
    path.pop();
  };
  walk(0, 0);
  let best = 0;
  for (const a of routes) {
    for (const b of routes) {
      const cells = new Set([...a, ...b]);
      let sum = 0;
      for (const k of cells) sum += grid[Math.floor(k / n)][k % n];
      best = Math.max(best, sum);
    }
  }
  return best;
}

