function berryHarvest(grid: number[][]): number {
  const n = grid.length;
  const NEG = -Infinity;
  let dp: number[][] = Array.from({ length: n }, () => new Array(n).fill(NEG));
  dp[0][0] = grid[0][0];
  for (let t = 1; t <= 2 * n - 2; t++) {
    const next: number[][] = Array.from({ length: n }, () => new Array(n).fill(NEG));
    const lo = Math.max(0, t - (n - 1)), hi = Math.min(n - 1, t);
    for (let r1 = lo; r1 <= hi; r1++) {
      const c1 = t - r1;
      if (grid[r1][c1] === -1) continue;
      for (let r2 = lo; r2 <= hi; r2++) {
        const c2 = t - r2;
        if (grid[r2][c2] === -1) continue;
        let prev = dp[r1][r2];
        if (r1 > 0) prev = Math.max(prev, dp[r1 - 1][r2]);
        if (r2 > 0) prev = Math.max(prev, dp[r1][r2 - 1]);
        if (r1 > 0 && r2 > 0) prev = Math.max(prev, dp[r1 - 1][r2 - 1]);
        if (prev === NEG) continue;
        next[r1][r2] = prev + grid[r1][c1] + (r1 !== r2 ? grid[r2][c2] : 0);
      }
    }
    dp = next;
  }
  return Math.max(0, dp[n - 1][n - 1]);
}

